from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class MiniappsMethods(BaseClient):
    """
    Методы группы 'Мини-аппы' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=72)
    @tracer.start_as_current_span("miniapp.rapi_miniapp_get")
    def rapi_miniapp_get(self, miniAppId: str) -> dict:
        """
        Получить информацию о мини-аппе
        :param miniAppId: Идентификатор мини-аппа
        """
        return self.post(
            "rapi/miniapp/get",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"miniAppId": miniAppId},
            },
        )
